/* ChaCha20 AVX2, 4 blocks in parallel (256 bytes/iter), plus Poly1305.
   Public-domain style implementation for benchmarking. */
#include <stdint.h>
#include <string.h>
#include <immintrin.h>

static inline __m256i rotl32_256(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static inline void qr(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b);
    *d = _mm256_xor_si256(*d, *a);
    *d = rotl32_256(*d, 16);
    *c = _mm256_add_epi32(*c, *d);
    *b = _mm256_xor_si256(*b, *c);
    *b = rotl32_256(*b, 12);
    *a = _mm256_add_epi32(*a, *b);
    *d = _mm256_xor_si256(*d, *a);
    *d = rotl32_256(*d, 8);
    *c = _mm256_add_epi32(*c, *d);
    *b = _mm256_xor_si256(*b, *c);
    *b = rotl32_256(*b, 7);
}

/* Transpose 4x4 blocks of 32-bit lanes so each ymm holds one word-position
   across 8 blocks? We do 4 blocks: state rows are 4 xmm conceptually.
   Layout: x[i] holds word i of 8 consecutive blocks? Simpler: 4 blocks,
   each ymm lane is one block. 8 lanes of uint32 -> 8 blocks at once. */

/* Process 8 blocks (512 bytes) at a time. */
static void chacha20_xor8(const uint32_t key[8], const uint32_t nonce[3],
                          uint32_t counter, const uint8_t *in, uint8_t *out, size_t bytes) {
    const __m256i c0 = _mm256_set1_epi32(0x61707865);
    const __m256i c1 = _mm256_set1_epi32(0x3320646e);
    const __m256i c2 = _mm256_set1_epi32(0x79622d32);
    const __m256i c3 = _mm256_set1_epi32(0x6b206574);
    const __m256i k0 = _mm256_set1_epi32(key[0]);
    const __m256i k1 = _mm256_set1_epi32(key[1]);
    const __m256i k2 = _mm256_set1_epi32(key[2]);
    const __m256i k3 = _mm256_set1_epi32(key[3]);
    const __m256i k4 = _mm256_set1_epi32(key[4]);
    const __m256i k5 = _mm256_set1_epi32(key[5]);
    const __m256i k6 = _mm256_set1_epi32(key[6]);
    const __m256i k7 = _mm256_set1_epi32(key[7]);
    const __m256i n0 = _mm256_set1_epi32(nonce[0]);
    const __m256i n1 = _mm256_set1_epi32(nonce[1]);
    const __m256i n2 = _mm256_set1_epi32(nonce[2]);
    const __m256i ctr_inc = _mm256_set1_epi32(8);

    size_t off = 0;
    while (off + 512 <= bytes) {
        __m256i ctr = _mm256_set_epi32(counter+7, counter+6, counter+5, counter+4,
                                       counter+3, counter+2, counter+1, counter+0);
        __m256i x0=c0,x1=c1,x2=c2,x3=c3;
        __m256i x4=k0,x5=k1,x6=k2,x7=k3,x8=k4,x9=k5,x10=k6,x11=k7;
        __m256i x12=ctr,x13=n0,x14=n1,x15=n2;

        for (int i = 0; i < 10; i++) {
            qr(&x0,&x4,&x8,&x12);
            qr(&x1,&x5,&x9,&x13);
            qr(&x2,&x6,&x10,&x14);
            qr(&x3,&x7,&x11,&x15);
            qr(&x0,&x5,&x10,&x15);
            qr(&x1,&x6,&x11,&x12);
            qr(&x2,&x7,&x8,&x13);
            qr(&x3,&x4,&x9,&x14);
        }
        x0 = _mm256_add_epi32(x0, c0); x1 = _mm256_add_epi32(x1, c1);
        x2 = _mm256_add_epi32(x2, c2); x3 = _mm256_add_epi32(x3, c3);
        x4 = _mm256_add_epi32(x4, k0); x5 = _mm256_add_epi32(x5, k1);
        x6 = _mm256_add_epi32(x6, k2); x7 = _mm256_add_epi32(x7, k3);
        x8 = _mm256_add_epi32(x8, k4); x9 = _mm256_add_epi32(x9, k5);
        x10= _mm256_add_epi32(x10,k6); x11= _mm256_add_epi32(x11,k7);
        x12= _mm256_add_epi32(x12,ctr);x13= _mm256_add_epi32(x13,n0);
        x14= _mm256_add_epi32(x14,n1); x15= _mm256_add_epi32(x15,n2);

        /* Transpose so bytes come out in block order.
           Each x holds word W of 8 blocks. We want, for each block, words 0..15.
           Do it lane by lane via extract — fine, the rounds dominate. */
        uint32_t w0[8],w1[8],w2[8],w3[8],w4[8],w5[8],w6[8],w7[8];
        uint32_t w8[8],w9[8],w10[8],w11[8],w12[8],w13[8],w14[8],w15[8];
        _mm256_storeu_si256((__m256i*)w0, x0); _mm256_storeu_si256((__m256i*)w1, x1);
        _mm256_storeu_si256((__m256i*)w2, x2); _mm256_storeu_si256((__m256i*)w3, x3);
        _mm256_storeu_si256((__m256i*)w4, x4); _mm256_storeu_si256((__m256i*)w5, x5);
        _mm256_storeu_si256((__m256i*)w6, x6); _mm256_storeu_si256((__m256i*)w7, x7);
        _mm256_storeu_si256((__m256i*)w8, x8); _mm256_storeu_si256((__m256i*)w9, x9);
        _mm256_storeu_si256((__m256i*)w10,x10);_mm256_storeu_si256((__m256i*)w11,x11);
        _mm256_storeu_si256((__m256i*)w12,x12);_mm256_storeu_si256((__m256i*)w13,x13);
        _mm256_storeu_si256((__m256i*)w14,x14);_mm256_storeu_si256((__m256i*)w15,x15);

        for (int b = 0; b < 8; b++) {
            uint32_t block[16] = {w0[b],w1[b],w2[b],w3[b],w4[b],w5[b],w6[b],w7[b],
                                  w8[b],w9[b],w10[b],w11[b],w12[b],w13[b],w14[b],w15[b]};
            const uint8_t *pi = in + off + b*64;
            uint8_t *po = out + off + b*64;
            const uint8_t *ks = (const uint8_t*)block;
            for (int j = 0; j < 64; j++) po[j] = pi[j] ^ ks[j];
        }
        off += 512;
        counter += 8;
        (void)ctr_inc;
    }
    /* tail: scalar */
    while (off < bytes) {
        uint32_t s[16] = {0x61707865,0x3320646e,0x79622d32,0x6b206574,
                          key[0],key[1],key[2],key[3],key[4],key[5],key[6],key[7],
                          counter, nonce[0], nonce[1], nonce[2]};
        uint32_t w[16];
        memcpy(w, s, 64);
        for (int i = 0; i < 10; i++) {
            #define QR(a,b,c,d) do { \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<16)|(w[d]>>16); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<12)|(w[b]>>20); \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<8)|(w[d]>>24); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<7)|(w[b]>>25); } while(0)
            QR(0,4,8,12); QR(1,5,9,13); QR(2,6,10,14); QR(3,7,11,15);
            QR(0,5,10,15); QR(1,6,11,12); QR(2,7,8,13); QR(3,4,9,14);
            #undef QR
        }
        for (int i = 0; i < 16; i++) w[i] += s[i];
        size_t take = bytes - off; if (take > 64) take = 64;
        const uint8_t *ks = (const uint8_t*)w;
        for (size_t j = 0; j < take; j++) out[off+j] = in[off+j] ^ ks[j];
        off += 64;
        counter++;
    }
}

/* Exported: XOR keystream (counter given as 32-bit) into out. */
void chacha20_xor(const uint8_t key[32], const uint8_t nonce[12], uint32_t counter,
                  const uint8_t *in, uint8_t *out, size_t len) {
    uint32_t kw[8], nw[3];
    memcpy(kw, key, 32);
    memcpy(nw, nonce, 12);
    chacha20_xor8(kw, nw, counter, in, out, len);
}
