#include <string.h>
#include <immintrin.h>

/* Poly1305, 26-bit limb, processes one block. r clamped. */
typedef struct {
    uint32_t r0, r1, r2, r3, r4;
    uint32_t s1, s2, s3, s4;
    uint32_t h0, h1, h2, h3, h4;
    uint8_t buf[16];
    size_t buf_used;
    uint8_t s[16]; /* second half of key, added at end */
} poly1305_ctx;

static void poly_init(poly1305_ctx *st, const uint8_t key[32]) {
    uint32_t t0 = (uint32_t)key[0] | ((uint32_t)key[1]<<8) | ((uint32_t)key[2]<<16) | ((uint32_t)key[3]<<24);
    uint32_t t1 = (uint32_t)key[4] | ((uint32_t)key[5]<<8) | ((uint32_t)key[6]<<16) | ((uint32_t)key[7]<<24);
    uint32_t t2 = (uint32_t)key[8] | ((uint32_t)key[9]<<8) | ((uint32_t)key[10]<<16) | ((uint32_t)key[11]<<24);
    uint32_t t3 = (uint32_t)key[12]| ((uint32_t)key[13]<<8)| ((uint32_t)key[14]<<16)| ((uint32_t)key[15]<<24);
    /* clamp */
    t0 &= 0x0fffffff; t1 &= 0x0ffffffc; t2 &= 0x0ffffffc; t3 &= 0x0ffffffc;
    st->r0 = t0 & 0x3ffffff;
    st->r1 = ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
    st->r2 = ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
    st->r3 = ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
    st->r4 = (t3 >> 8) & 0x3ffffff;
    st->s1 = st->r1 * 5; st->s2 = st->r2 * 5; st->s3 = st->r3 * 5; st->s4 = st->r4 * 5;
    st->h0 = st->h1 = st->h2 = st->h3 = st->h4 = 0;
    st->buf_used = 0;
    memcpy(st->s, key + 16, 16);
}

static void poly_block(poly1305_ctx *st, const uint8_t block[16], uint32_t hibit) {
    uint32_t t0 = (uint32_t)block[0] | ((uint32_t)block[1]<<8) | ((uint32_t)block[2]<<16) | ((uint32_t)block[3]<<24);
    uint32_t t1 = (uint32_t)block[4] | ((uint32_t)block[5]<<8) | ((uint32_t)block[6]<<16) | ((uint32_t)block[7]<<24);
    uint32_t t2 = (uint32_t)block[8] | ((uint32_t)block[9]<<8) | ((uint32_t)block[10]<<16)| ((uint32_t)block[11]<<24);
    uint32_t t3 = (uint32_t)block[12]| ((uint32_t)block[13]<<8)| ((uint32_t)block[14]<<16)| ((uint32_t)block[15]<<24);

    uint32_t h0 = st->h0 + (t0 & 0x3ffffff);
    uint32_t h1 = st->h1 + (((t0 >> 26) | (t1 << 6)) & 0x3ffffff);
    uint32_t h2 = st->h2 + (((t1 >> 20) | (t2 << 12)) & 0x3ffffff);
    uint32_t h3 = st->h3 + (((t2 >> 14) | (t3 << 18)) & 0x3ffffff);
    uint32_t h4 = st->h4 + ((t3 >> 8) | (hibit << 24));

    uint64_t d0 = (uint64_t)h0*st->r0 + (uint64_t)h1*st->s4 + (uint64_t)h2*st->s3 + (uint64_t)h3*st->s2 + (uint64_t)h4*st->s1;
    uint64_t d1 = (uint64_t)h0*st->r1 + (uint64_t)h1*st->r0 + (uint64_t)h2*st->s4 + (uint64_t)h3*st->s3 + (uint64_t)h4*st->s2;
