typedef struct {
    const uint32_t *key, *nonce;
    const uint8_t *in; uint8_t *out;
    uint32_t counter; size_t bytes;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    chacha20_range(j->key, j->nonce, j->counter, j->in, j->out, j->bytes);
    return NULL;
}

int main(int argc, char **argv) {
    int nthreads = argc > 1 ? atoi(argv[1]) : 6;
    size_t N = 40 * 1000 * 1000;
    uint8_t *in = aligned_alloc(64, N);
    uint8_t *out = aligned_alloc(64, N);
    memset(in, 0x42, N);
    uint32_t key[8] = {1,2,3,4,5,6,7,8};
    uint32_t nonce[3] = {9,10,11};

    /* warmup */
    chacha20_range(key, nonce, 0, in, out, 4096);

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int reps = 5;
    for (int r = 0; r < reps; r++) {
        pthread_t th[16];
        job_t jobs[16];
        size_t chunk = (N / nthreads) & ~(size_t)511;
        size_t off = 0;
        for (int i = 0; i < nthreads; i++) {
            size_t len = (i == nthreads-1) ? (N - off) : chunk;
            jobs[i] = (job_t){key, nonce, in+off, out+off, (uint32_t)(off/64), len};
            pthread_create(&th[i], NULL, worker, &jobs[i]);
            off += len;
        }
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + 1e-9*(t1.tv_nsec - t0.tv_nsec);
    printf("threads=%d  %.1f MB/s\n", nthreads, (N * reps / dt) / 1e6);
    free(in); free(out);
    return 0;
}
