        pthread_mutex_lock(&pool.mu);
        while (pool.pending == 0 && !pool.shutdown)
            pthread_cond_wait(&pool.cv_job, &pool.mu);
        if (pool.shutdown) { pthread_mutex_unlock(&pool.mu); return NULL; }
        int idx = pool.next++;
        pool.pending--;
        job_t j = pool.jobs[idx];
        pthread_mutex_unlock(&pool.mu);
        chacha20_range(j.key, j.nonce, j.counter, j.in, j.out, j.bytes);
        pthread_mutex_lock(&pool.mu);
        pool.inflight--;
        if (pool.inflight == 0) pthread_cond_signal(&pool.cv_done);
        pthread_mutex_unlock(&pool.mu);
    }
}

static void pool_init(void) {
    if (threads_started) return;
    memset(&pool, 0, sizeof(pool));
    pthread_mutex_init(&pool.mu, NULL);
    pthread_cond_init(&pool.cv_job, NULL);
    pthread_cond_init(&pool.cv_done, NULL);
    pool.nthreads = NTHREADS;
    for (int i = 0; i < NTHREADS; i++)
        pthread_create(&pool_threads[i], NULL, pool_worker, NULL);
    threads_started = 1;
}

static void chacha_parallel(const uint32_t key[8], const uint32_t nonce[3],
                            const uint8_t *in, uint8_t *out, size_t len) {
    if (len < 256 * 1024) { chacha20_range(key, nonce, 1, in, out, len); return; }
    pool_init();
    int nt = NTHREADS;
    size_t chunk = (len / nt) & ~(size_t)511;
    if (chunk == 0) { chacha20_range(key, nonce, 1, in, out, len); return; }
    pthread_mutex_lock(&pool.mu);
    size_t off = 0;
    int n = 0;
    for (int i = 0; i < nt; i++) {
        size_t blen = (i == nt - 1) ? (len - off) : chunk;
        pool.jobs[n] = (job_t){key, nonce, in + off, out + off, (uint32_t)(1 + off / 64), blen};
        off += blen; n++;
        if (off >= len) break;
    }
    pool.next = 0;
    pool.pending = n;
    pool.inflight = n;
    pthread_cond_broadcast(&pool.cv_job);
    while (pool.inflight > 0) pthread_cond_wait(&pool.cv_done, &pool.mu);
    pthread_mutex_unlock(&pool.mu);
}

/* RFC 8439 AEAD construction. */
static void pad16_update(poly_st *st, size_t len) {
    size_t rem = len & 15;
    if (rem) {
        uint8_t z[16] = {0};
        poly_update(st, z, 16 - rem);
    }
}

void chacha20poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                              const uint8_t *aad, size_t aad_len,
                              const uint8_t *pt, size_t pt_len,
                              uint8_t *ct, uint8_t tag[16]) {
    uint32_t kw[8], nw[3];
    memcpy(kw, key, 32);
    memcpy(nw, nonce, 12);
    /* block 0 -> poly key */
    uint8_t poly_key[64];
    uint8_t zeros[64] = {0};
    chacha20_range(kw, nw, 0, zeros, poly_key, 64);

    chacha_parallel(kw, nw, pt, ct, pt_len);

    poly_st st;
    poly_init(&st, poly_key);
    if (aad && aad_len) poly_update(&st, aad, aad_len);
    pad16_update(&st, aad_len);
    poly_update(&st, ct, pt_len);
    pad16_update(&st, pt_len);
    uint8_t lens[16];
    uint64_t al = aad_len, pl = pt_len;
    memcpy(lens, &al, 8); memcpy(lens + 8, &pl, 8);
    poly_update(&st, lens, 16);
    poly_finish(&st, tag);
}
