typedef struct { const uint32_t *key,*nonce; const uint8_t *in; uint8_t *out; uint32_t counter; size_t bytes; } job_t;
typedef struct {
    pthread_mutex_t mu; pthread_cond_t cv_job, cv_done;
    int shutdown, pending, inflight, next, started;
    job_t jobs[NTHREADS];
} pool_t;
static pool_t pool;
static pthread_t pool_threads[NTHREADS];
static void *pool_worker(void *arg) {
    (void)arg;
    for (;;) {
        pthread_mutex_lock(&pool.mu);
        while (pool.pending == 0 && !pool.shutdown) pthread_cond_wait(&pool.cv_job, &pool.mu);
        if (pool.shutdown) { pthread_mutex_unlock(&pool.mu); return NULL; }
        int idx = pool.next++; pool.pending--; job_t j = pool.jobs[idx];
        pthread_mutex_unlock(&pool.mu);
        chacha20_range(j.key, j.nonce, j.counter, j.in, j.out, j.bytes);
        pthread_mutex_lock(&pool.mu);
        pool.inflight--;
        if (pool.inflight == 0) pthread_cond_signal(&pool.cv_done);
        pthread_mutex_unlock(&pool.mu);
    }
}
static void pool_init(void) {
    if (pool.started) return;
    pthread_mutex_init(&pool.mu, NULL); pthread_cond_init(&pool.cv_job, NULL); pthread_cond_init(&pool.cv_done, NULL);
    pool.started = 1;
    for (int i = 0; i < NTHREADS; i++) pthread_create(&pool_threads[i], NULL, pool_worker, NULL);
