    pthread_mutex_lock(&pool.mu);
    size_t off = 0; int n = 0;
    for (int i = 0; i < NTHREADS; i++) {
        size_t blen = (i == NTHREADS-1) ? (len - off) : chunk;
        pool.jobs[n++] = (job_t){key, nonce, in+off, out+off, (uint32_t)(1 + off/64), blen};
        off += blen; if (off >= len) break;
    }
    pool.next = 0; pool.pending = n; pool.inflight = n;
    pthread_cond_broadcast(&pool.cv_job);
    while (pool.inflight > 0) pthread_cond_wait(&pool.cv_done, &pool.mu);
    pthread_mutex_unlock(&pool.mu);
}

static EVP_MAC *mac = NULL;
static __thread EVP_MAC_CTX *tl_ctx = NULL;
static void poly_tag(const uint8_t polykey[32], const uint8_t *aad, size_t aad_len,
                     const uint8_t *ct, size_t ct_len, uint8_t tag[16]) {
    if (!mac) mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    if (!tl_ctx) tl_ctx = EVP_MAC_CTX_new(mac);
    EVP_MAC_init(tl_ctx, polykey, 32, NULL);
    if (aad && aad_len) EVP_MAC_update(tl_ctx, aad, aad_len);
    size_t rem = aad_len & 15;
    if (rem) { uint8_t z[16]={0}; EVP_MAC_update(tl_ctx, z, 16-rem); }
    EVP_MAC_update(tl_ctx, ct, ct_len);
    rem = ct_len & 15;
    if (rem) { uint8_t z[16]={0}; EVP_MAC_update(tl_ctx, z, 16-rem); }
    uint8_t lens[16]; uint64_t al=aad_len, pl=ct_len;
    memcpy(lens, &al, 8); memcpy(lens+8, &pl, 8);
    EVP_MAC_update(tl_ctx, lens, 16);
    size_t outl=16; EVP_MAC_final(tl_ctx, tag, &outl, 16);
