    struct timespec t0,t1; clock_gettime(CLOCK_MONOTONIC,&t0);
    int reps=4;
    for(int i=0;i<reps;i++) chacha20poly1305_encrypt(key, nonce, aad, 32, pt, N, ct, tag);
