/* Measure OpenSSL Poly1305 on many small sequential updates vs one big one. */
#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
int main() {
    size_t N = 40*1000*1000;
    uint8_t *m = malloc(N); memset(m, 0xab, N);
    uint8_t key[32]; for (int i=0;i<32;i++) key[i]=i*7+3;
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    EVP_MAC_CTX *ctx = EVP_MAC_CTX_new(mac);
    uint8_t tag[16]; size_t outlen;
    int reps = 3;
    for (int cs_i = 0; cs_i < 5; cs_i++) {
        size_t chunk = (size_t[]){16384, 65536, 262144, 1048576, N}[cs_i];
        struct timespec t0,t1; clock_gettime(CLOCK_MONOTONIC,&t0);
        for (int r=0;r<reps;r++) {
            EVP_MAC_init(ctx, key, 32, NULL);
