/* Pipelined ChaCha20-Poly1305: each worker encrypts its chunk then feeds the
   ciphertext to its own Poly1305. The main thread combines the partial
   authenticators (Poly1305 is a polynomial hash, so partial powers combine). */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <immintrin.h>
#include <openssl/evp.h>
#include <stdio.h>
#include <time.h>

#define NTHREADS 6

static inline void qr(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b);
    *d = _mm256_xor_si256(*d, *a);
    *d = _mm256_or_si256(_mm256_slli_epi32(*d, 16), _mm256_srli_epi32(*d, 16));
    *c = _mm256_add_epi32(*c, *d);
    *b = _mm256_xor_si256(*b, *c);
    *b = _mm256_or_si256(_mm256_slli_epi32(*b, 12), _mm256_srli_epi32(*b, 20));
    *a = _mm256_add_epi32(*a, *b);
    *d = _mm256_xor_si256(*d, *a);
    *d = _mm256_or_si256(_mm256_slli_epi32(*d, 8), _mm256_srli_epi32(*d, 24));
    *c = _mm256_add_epi32(*c, *d);
    *b = _mm256_xor_si256(*b, *c);
    *b = _mm256_or_si256(_mm256_slli_epi32(*b, 7), _mm256_srli_epi32(*b, 25));
}

static void chacha20_range(const uint32_t key[8], const uint32_t nonce[3],
                           uint32_t counter, const uint8_t *in, uint8_t *out, size_t bytes) {
    const __m256i c0=_mm256_set1_epi32(0x61707865), c1=_mm256_set1_epi32(0x3320646e);
    const __m256i c2=_mm256_set1_epi32(0x79622d32), c3=_mm256_set1_epi32(0x6b206574);
    const __m256i k0=_mm256_set1_epi32(key[0]), k1=_mm256_set1_epi32(key[1]);
    const __m256i k2=_mm256_set1_epi32(key[2]), k3=_mm256_set1_epi32(key[3]);
    const __m256i k4=_mm256_set1_epi32(key[4]), k5=_mm256_set1_epi32(key[5]);
    const __m256i k6=_mm256_set1_epi32(key[6]), k7=_mm256_set1_epi32(key[7]);
    const __m256i n0=_mm256_set1_epi32(nonce[0]), n1=_mm256_set1_epi32(nonce[1]), n2=_mm256_set1_epi32(nonce[2]);
    size_t off = 0;
    while (off + 512 <= bytes) {
        __m256i ctr=_mm256_set_epi32(counter+7,counter+6,counter+5,counter+4,counter+3,counter+2,counter+1,counter);
        __m256i x0=c0,x1=c1,x2=c2,x3=c3,x4=k0,x5=k1,x6=k2,x7=k3,x8=k4,x9=k5,x10=k6,x11=k7;
        __m256i x12=ctr,x13=n0,x14=n1,x15=n2;
        for (int i=0;i<10;i++) {
            qr(&x0,&x4,&x8,&x12); qr(&x1,&x5,&x9,&x13); qr(&x2,&x6,&x10,&x14); qr(&x3,&x7,&x11,&x15);
            qr(&x0,&x5,&x10,&x15); qr(&x1,&x6,&x11,&x12); qr(&x2,&x7,&x8,&x13); qr(&x3,&x4,&x9,&x14);
        }
        x0=_mm256_add_epi32(x0,c0); x1=_mm256_add_epi32(x1,c1); x2=_mm256_add_epi32(x2,c2); x3=_mm256_add_epi32(x3,c3);
        x4=_mm256_add_epi32(x4,k0); x5=_mm256_add_epi32(x5,k1); x6=_mm256_add_epi32(x6,k2); x7=_mm256_add_epi32(x7,k3);
        x8=_mm256_add_epi32(x8,k4); x9=_mm256_add_epi32(x9,k5); x10=_mm256_add_epi32(x10,k6); x11=_mm256_add_epi32(x11,k7);
        x12=_mm256_add_epi32(x12,ctr); x13=_mm256_add_epi32(x13,n0); x14=_mm256_add_epi32(x14,n1); x15=_mm256_add_epi32(x15,n2);
        uint32_t W[16][8];
        _mm256_storeu_si256((__m256i*)W[0],x0); _mm256_storeu_si256((__m256i*)W[1],x1);
        _mm256_storeu_si256((__m256i*)W[2],x2); _mm256_storeu_si256((__m256i*)W[3],x3);
        _mm256_storeu_si256((__m256i*)W[4],x4); _mm256_storeu_si256((__m256i*)W[5],x5);
        _mm256_storeu_si256((__m256i*)W[6],x6); _mm256_storeu_si256((__m256i*)W[7],x7);
        _mm256_storeu_si256((__m256i*)W[8],x8); _mm256_storeu_si256((__m256i*)W[9],x9);
        _mm256_storeu_si256((__m256i*)W[10],x10);_mm256_storeu_si256((__m256i*)W[11],x11);
        _mm256_storeu_si256((__m256i*)W[12],x12);_mm256_storeu_si256((__m256i*)W[13],x13);
        _mm256_storeu_si256((__m256i*)W[14],x14);_mm256_storeu_si256((__m256i*)W[15],x15);
        for (int b=0;b<8;b++) {
            uint32_t block[16];
            for (int i=0;i<16;i++) block[i]=W[i][b];
            const uint8_t *pi=in+off+(size_t)b*64; uint8_t *po=out+off+(size_t)b*64;
            const uint8_t *ks=(const uint8_t*)block;
            for (int j=0;j<64;j++) po[j]=pi[j]^ks[j];
        }
        off += 512; counter += 8;
    }
    while (off < bytes) {
        uint32_t s[16]={0x61707865,0x3320646e,0x79622d32,0x6b206574,
            key[0],key[1],key[2],key[3],key[4],key[5],key[6],key[7],
            counter,nonce[0],nonce[1],nonce[2]};
        uint32_t w[16]; memcpy(w,s,64);
        for (int i=0;i<10;i++) {
            #define QR(a,b,c,d) do{w[a]+=w[b];w[d]^=w[a];w[d]=(w[d]<<16)|(w[d]>>16);\
                w[c]+=w[d];w[b]^=w[c];w[b]=(w[b]<<12)|(w[b]>>20);\
                w[a]+=w[b];w[d]^=w[a];w[d]=(w[d]<<8)|(w[d]>>24);\
                w[c]+=w[d];w[b]^=w[c];w[b]=(w[b]<<7)|(w[b]>>25);}while(0)
            QR(0,4,8,12);QR(1,5,9,13);QR(2,6,10,14);QR(3,7,11,15);
            QR(0,5,10,15);QR(1,6,11,12);QR(2,7,8,13);QR(3,4,9,14);
            #undef QR
        }
        for (int i=0;i<16;i++) w[i]+=s[i];
        size_t take=bytes-off; if(take>64) take=64;
        const uint8_t *ks=(const uint8_t*)w;
        for (size_t j=0;j<take;j++) out[off+j]=in[off+j]^ks[j];
        off+=64; counter++;
    }
}

/* ---------- Poly1305 in 26-bit limbs, with state export/import and r^n ---------- */
typedef struct { uint32_t h[5]; } poly_acc;

typedef struct {
    uint32_t r[5];   /* r limbs */
    uint32_t s5[4];  /* 5*r[1..4] */
} poly_key;

static void poly_key_init(poly_key *k, const uint8_t key[16]) {
    uint32_t t0,t1,t2,t3;
    memcpy(&t0,key,4); memcpy(&t1,key+4,4); memcpy(&t2,key+8,4); memcpy(&t3,key+12,4);
    t0&=0x0fffffff; t1&=0x0ffffffc; t2&=0x0ffffffc; t3&=0x0ffffffc;
    k->r[0]=t0 & 0x3ffffff;
    k->r[1]=((t0>>26)|(t1<<6)) & 0x3ffffff;
    k->r[2]=((t1>>20)|(t2<<12)) & 0x3ffffff;
    k->r[3]=((t2>>14)|(t3<<18)) & 0x3ffffff;
    k->r[4]=(t3>>8) & 0x3ffffff;
    k->s5[0]=k->r[1]*5; k->s5[1]=k->r[2]*5; k->s5[2]=k->r[3]*5; k->s5[3]=k->r[4]*5;
}

/* h = h*r + block, fully reduced to 26-bit limbs with one extra carry pass */
static void poly_block(const poly_key *k, poly_acc *a, const uint8_t b[16], uint32_t hibit) {
    uint32_t t0,t1,t2,t3;
    memcpy(&t0,b,4); memcpy(&t1,b+4,4); memcpy(&t2,b+8,4); memcpy(&t3,b+12,4);
    uint32_t h0=a->h[0]+(t0 & 0x3ffffff);
    uint32_t h1=a->h[1]+(((t0>>26)|(t1<<6)) & 0x3ffffff);
    uint32_t h2=a->h[2]+(((t1>>20)|(t2<<12)) & 0x3ffffff);
    uint32_t h3=a->h[3]+(((t2>>14)|(t3<<18)) & 0x3ffffff);
    uint32_t h4=a->h[4]+((t3>>8)|(hibit<<24));
    uint32_t r0=k->r[0],r1=k->r[1],r2=k->r[2],r3=k->r[3],r4=k->r[4];
    uint32_t s1=k->s5[0],s2=k->s5[1],s3=k->s5[2],s4=k->s5[3];
    uint64_t d0=(uint64_t)h0*r0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
    uint64_t d1=(uint64_t)h0*r1+(uint64_t)h1*r0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
    uint64_t d2=(uint64_t)h0*r2+(uint64_t)h1*r1+(uint64_t)h2*r0+(uint64_t)h3*s4+(uint64_t)h4*s3;
    uint64_t d3=(uint64_t)h0*r3+(uint64_t)h1*r2+(uint64_t)h2*r1+(uint64_t)h3*r0+(uint64_t)h4*s4;
    uint64_t d4=(uint64_t)h0*r4+(uint64_t)h1*r3+(uint64_t)h2*r2+(uint64_t)h3*r1+(uint64_t)h4*r0;
    uint64_t c;
    c=d0>>26; a->h[0]=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; a->h[1]=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; a->h[2]=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; a->h[3]=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; a->h[4]=(uint32_t)d4 & 0x3ffffff; a->h[0]+=(uint32_t)c*5;
    c=a->h[0]>>26; a->h[0]&=0x3ffffff; a->h[1]+=(uint32_t)c;
}

/* multiply accumulator by r^n (given as 5 limbs) without adding a block: h = h * rn */
static void poly_mul(const uint32_t rn[5], const uint32_t rn5[4], poly_acc *a) {
    uint32_t h0=a->h[0],h1=a->h[1],h2=a->h[2],h3=a->h[3],h4=a->h[4];
    uint32_t r0=rn[0],r1=rn[1],r2=rn[2],r3=rn[3],r4=rn[4];
    uint32_t s1=rn5[0],s2=rn5[1],s3=rn5[2],s4=rn5[3];
    uint64_t d0=(uint64_t)h0*r0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
    uint64_t d1=(uint64_t)h0*r1+(uint64_t)h1*r0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
    uint64_t d2=(uint64_t)h0*r2+(uint64_t)h1*r1+(uint64_t)h2*r0+(uint64_t)h3*s4+(uint64_t)h4*s3;
    uint64_t d3=(uint64_t)h0*r3+(uint64_t)h1*r2+(uint64_t)h2*r1+(uint64_t)h3*r0+(uint64_t)h4*s4;
    uint64_t d4=(uint64_t)h0*r4+(uint64_t)h1*r3+(uint64_t)h2*r2+(uint64_t)h3*r1+(uint64_t)h4*r0;
    uint64_t c;
    c=d0>>26; a->h[0]=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; a->h[1]=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; a->h[2]=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; a->h[3]=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; a->h[4]=(uint32_t)d4 & 0x3ffffff; a->h[0]+=(uint32_t)c*5;
    c=a->h[0]>>26; a->h[0]&=0x3ffffff; a->h[1]+=(uint32_t)c;
}

/* add two accumulators (both reduced) */
static void poly_add(poly_acc *dst, const poly_acc *src) {
    uint64_t c;
    uint64_t h0=(uint64_t)dst->h[0]+src->h[0];
    uint64_t h1=(uint64_t)dst->h[1]+src->h[1];
    uint64_t h2=(uint64_t)dst->h[2]+src->h[2];
    uint64_t h3=(uint64_t)dst->h[3]+src->h[3];
    uint64_t h4=(uint64_t)dst->h[4]+src->h[4];
    c=h0>>26; dst->h[0]=(uint32_t)h0 & 0x3ffffff; h1+=c;
    c=h1>>26; dst->h[1]=(uint32_t)h1 & 0x3ffffff; h2+=c;
    c=h2>>26; dst->h[2]=(uint32_t)h2 & 0x3ffffff; h3+=c;
    c=h3>>26; dst->h[3]=(uint32_t)h3 & 0x3ffffff; h4+=c;
    c=h4>>26; dst->h[4]=(uint32_t)h4 & 0x3ffffff; dst->h[0]+=(uint32_t)c*5;
    c=dst->h[0]>>26; dst->h[0]&=0x3ffffff; dst->h[1]+=(uint32_t)c;
}

/* r^(2^k) table for combining. We need r^nblocks where nblocks can be large.
   Compute by exponentiation by squaring per call (nblocks ~ 4e7/16 = 2.6e6, ~22 squarings). */

static void limb_mul(const uint32_t a[5], const uint32_t b[5], const uint32_t b5[4], uint32_t out[5]) {
    uint32_t h0=a[0],h1=a[1],h2=a[2],h3=a[3],h4=a[4];
    uint32_t r0=b[0],r1=b[1],r2=b[2],r3=b[3],r4=b[4];
    uint32_t s1=b5[0],s2=b5[1],s3=b5[2],s4=b5[3];
    uint64_t d0=(uint64_t)h0*r0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
    uint64_t d1=(uint64_t)h0*r1+(uint64_t)h1*r0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
    uint64_t d2=(uint64_t)h0*r2+(uint64_t)h1*r1+(uint64_t)h2*r0+(uint64_t)h3*s4+(uint64_t)h4*s3;
    uint64_t d3=(uint64_t)h0*r3+(uint64_t)h1*r2+(uint64_t)h2*r1+(uint64_t)h3*r0+(uint64_t)h4*s4;
    uint64_t d4=(uint64_t)h0*r4+(uint64_t)h1*r3+(uint64_t)h2*r2+(uint64_t)h3*r1+(uint64_t)h4*r0;
    uint64_t c;
    c=d0>>26; out[0]=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; out[1]=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; out[2]=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; out[3]=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; out[4]=(uint32_t)d4 & 0x3ffffff; out[0]+=(uint32_t)c*5;
    c=out[0]>>26; out[0]&=0x3ffffff; out[1]+=(uint32_t)c;
}

/* compute r^n into out[5], out5[4] */
static void poly_pow(const poly_key *k, uint64_t n, uint32_t out[5], uint32_t out5[4]) {
    uint32_t base[5], base5[4];
    memcpy(base, k->r, sizeof(base));
    memcpy(base5, k->s5, sizeof(base5));
    uint32_t res[5] = {1,0,0,0,0}; /* identity */
    while (n) {
        if (n & 1) {
            uint32_t tmp[5];
            uint32_t res5[4] = {res[1]*5, res[2]*5, res[3]*5, res[4]*5};
            /* res = res * base */
            limb_mul(res, base, base5, tmp);
            memcpy(res, tmp, sizeof(res));
        }
        uint32_t sq[5];
        limb_mul(base, base, base5, sq);
        memcpy(base, sq, sizeof(base));
        base5[0]=base[1]*5; base5[1]=base[2]*5; base5[2]=base[3]*5; base5[3]=base[4]*5;
        n >>= 1;
    }
    memcpy(out, res, sizeof(uint32_t)*5);
    out5[0]=out[1]*5; out5[1]=out[2]*5; out5[2]=out[3]*5; out5[3]=out[4]*5;
}

static void poly_finish(poly_acc *a, const uint8_t skey[16], uint8_t tag[16]) {
    uint32_t h0=a->h[0],h1=a->h[1],h2=a->h[2],h3=a->h[3],h4=a->h[4],c;
    c=h1>>26; h1&=0x3ffffff; h2+=c; c=h2>>26; h2&=0x3ffffff; h3+=c;
    c=h3>>26; h3&=0x3ffffff; h4+=c; c=h4>>26; h4&=0x3ffffff; h0+=c*5; c=h0>>26; h0&=0x3ffffff; h1+=c;
    uint32_t g0=h0+5; c=g0>>26; g0&=0x3ffffff;
    uint32_t g1=h1+c; c=g1>>26; g1&=0x3ffffff;
    uint32_t g2=h2+c; c=g2>>26; g2&=0x3ffffff;
    uint32_t g3=h3+c; c=g3>>26; g3&=0x3ffffff;
    uint32_t g4=h4+c-(1u<<26);
    uint32_t mask=(g4>>31)-1u;
    g0&=mask; g1&=mask; g2&=mask; g3&=mask; g4&=mask; mask=~mask;
    h0=(h0&mask)|g0; h1=(h1&mask)|g1; h2=(h2&mask)|g2; h3=(h3&mask)|g3; h4=(h4&mask)|g4;
    uint32_t s0,s1,s2,s3; memcpy(&s0,skey,4); memcpy(&s1,skey+4,4); memcpy(&s2,skey+8,4); memcpy(&s3,skey+12,4);
    uint64_t a0=(uint64_t)(h0|(h1<<26))+s0;
    uint64_t a1=((((uint64_t)h1>>6)|((uint64_t)h2<<20))&0xffffffffu)+s1+(a0>>32);
    uint64_t a2=((((uint64_t)h2>>12)|((uint64_t)h3<<14))&0xffffffffu)+s2+(a1>>32);
    uint64_t a3=((((uint64_t)h3>>18)|((uint64_t)h4<<8))&0xffffffffu)+s3+(a2>>32);
    uint32_t o0=(uint32_t)a0,o1=(uint32_t)a1,o2=(uint32_t)a2,o3=(uint32_t)a3;
    memcpy(tag,&o0,4); memcpy(tag+4,&o1,4); memcpy(tag+8,&o2,4); memcpy(tag+12,&o3,4);
}

static void poly_update_bytes(const poly_key *k, poly_acc *a, const uint8_t *m, size_t len) {
    size_t off = 0;
    while (off + 16 <= len) { poly_block(k, a, m+off, 1); off += 16; }
    if (off < len) {
        uint8_t b[16]; memset(b,0,16); memcpy(b, m+off, len-off); b[len-off]=1;
        poly_block(k, a, b, 0);
    }
}

/* ---------- pipeline ---------- */
typedef struct {
    const uint32_t *kw; const uint32_t *nw;
    const uint8_t *in; uint8_t *out;
    uint32_t counter; size_t bytes;
    const poly_key *pk;
    poly_acc acc;
} pjob_t;

static void *pworker(void *arg) {
    pjob_t *j = arg;
    chacha20_range(j->kw, j->nw, j->counter, j->in, j->out, j->bytes);
    memset(&j->acc, 0, sizeof(j->acc));
    poly_update_bytes(j->pk, &j->acc, j->out, j->bytes);
    return NULL;
}

static void chacha20poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                                     const uint8_t *aad, size_t aad_len,
                                     const uint8_t *pt, size_t pt_len,
                                     uint8_t *ct, uint8_t tag[16]) {
    uint32_t kw[8], nw[3];
    memcpy(kw, key, 32); memcpy(nw, nonce, 12);
    uint8_t pkraw[64], zeros[64]={0};
    chacha20_range(kw, nw, 0, zeros, pkraw, 64);
    poly_key pk; poly_key_init(&pk, pkraw);

    int nt = NTHREADS;
    if (pt_len < 1024*1024) nt = 1;
    size_t chunk = (pt_len / nt) & ~(size_t)511;
    if (chunk == 0) nt = 1;

    pthread_t th[NTHREADS]; pjob_t jobs[NTHREADS];
    size_t off = 0;
    for (int i = 0; i < nt; i++) {
        size_t len = (i == nt-1) ? (pt_len - off) : chunk;
        jobs[i].kw = kw; jobs[i].nw = nw; jobs[i].in = pt+off; jobs[i].out = ct+off;
        jobs[i].counter = (uint32_t)(1 + off/64); jobs[i].bytes = len; jobs[i].pk = &pk;
        if (nt > 1) pthread_create(&th[i], NULL, pworker, &jobs[i]);
        else pworker(&jobs[i]);
        off += len;
    }
    if (nt > 1) for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);

    /* combine: acc = acc0 + acc1*r^{n0} + acc2*r^{n0+n1} + ... */
    poly_acc total; memset(&total, 0, sizeof(total));
    uint64_t blocks_before = 0;
    /* AAD first */
    if (aad && aad_len) {
        poly_update_bytes(&pk, &total, aad, aad_len);
        size_t aad_blocks = (aad_len + 15) / 16;
        blocks_before = aad_blocks;
    }
    for (int i = 0; i < nt; i++) {
        if (blocks_before) {
            uint32_t rn[5], rn5[4];
            poly_pow(&pk, blocks_before, rn, rn5);
            poly_mul(rn, rn5, &jobs[i].acc);
        }
        poly_add(&total, &jobs[i].acc);
