/* Cost of a cheap running checksum: acc = (acc + block) * r  mod 2^61-1, per 16 bytes. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
int main(){
    size_t N=40*1000*1000; uint8_t *m=malloc(N); memset(m,0xab,N);
    uint64_t r=0x1fffffffffffffffULL; /* fits */
    const uint64_t P61 = (1ull<<61) - 1;
    struct timespec t0,t1; clock_gettime(CLOCK_MONOTONIC,&t0);
    int reps=3; uint64_t acc=0;
    for(int rep=0;rep<reps;rep++){
        acc=0;
        for(size_t o=0;o+16<=N;o+=16){
            uint64_t b0,b1; memcpy(&b0,m+o,8); memcpy(&b1,m+o+8,8);
            /* fold 128-bit block + hibit into mod 2^61-1: value = b0 + b1*2^64 + 2^128 */
            __uint128_t v = (__uint128_t)b0 + ((__uint128_t)b1<<64);
            /* + 2^128 ≡ 2^(128 mod 61) */
            uint64_t x = (uint64_t)v + (uint64_t)(v>>61) + (uint64_t)(v>>122);
            x = (x & P61) + (x >> 61);
            acc += x + 1; /* hibit folded: 2^128 mod 2^61-1 = 2^(128%61)=2^6 = 64 */
            acc = (acc & P61) + (acc >> 61);
            /* multiply by r mod 2^61-1 */
            __uint128_t p = (__uint128_t)acc * r;
            uint64_t y = (uint64_t)p + (uint64_t)(p>>61);
            acc = (y & P61) + (y >> 61);
            if (acc >= P61) acc -= P61;
        }
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+1e-9*(t1.tv_nsec-t0.tv_nsec);
    printf("checksum: %.1f MB/s (acc=%llx)\n", (N*reps/dt)/1e6, (unsigned long long)acc);
    return 0;
}
