#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#define NT 6
typedef struct { uint8_t *dst, *src; size_t n; } job;
static void *w(void *a){ job *j=a; memcpy(j->dst, j->src, j->n); return NULL; }
int main(){
    size_t N=256*1024*1024;
    uint8_t *s=aligned_alloc(64,N), *d=aligned_alloc(64,N);
    memset(s,1,N);
    struct timespec t0,t1; clock_gettime(CLOCK_MONOTONIC,&t0);
    int reps=4;
    for(int r=0;r<reps;r++){
        pthread_t th[NT]; job jobs[NT]; size_t chunk=N/NT, off=0;
        for(int i=0;i<NT;i++){ size_t len=(i==NT-1)?N-off:chunk; jobs[i]=(job){d+off,s+off,len}; pthread_create(&th[i],NULL,w,&jobs[i]); off+=len; }
        for(int i=0;i<NT;i++) pthread_join(th[i],NULL);
    }
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+1e-9*(t1.tv_nsec-t0.tv_nsec);
    printf("parallel memcpy x%d: %.1f MB/s (copy), equiv cipher ceiling %.1f MB/s\n", NT, (N*reps/dt)/1e6, (N*reps/dt)/2/1e6);
    return 0;
}
